  tools.exec_command({cmd:"rg -n -i 'namespace|名前空間' packages/phpstan-guard-rules/docs packages/guard-php/docs packages/phpstan-guard-rules/src packages/guard-php/src",max_output_tokens:11000}),
  tools.exec_command({cmd:"rg --files -g 'AGENTS.md' -g '*Namespace*' -g '*Forbidden*' -g '*Disallow*' -g '*Banned*' -g '*Ban*'",max_output_tokens:3000})
]); for(let i=0;i<results.length;i++) text({i,...results[i]});

